using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains;
using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Measurements;
using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Temporal;
namespace Astronomy.MediaFactory.Core.KnowledgeFoundation.Validation.Temporal;
public sealed class AstronomyCyclePeriodValidationRule:TemporalRuleBase{public const string Id="temporal.cycle-period.dimension"; public override string RuleId=>Id; public override int Order=>400; protected override IEnumerable<AstronomyKnowledgeValidationIssue> ValidateTyped(AstronomyTemporalPatternPayload p,AstronomyKnowledgeValidationContext c){var cp=p.Pattern.CyclePeriod; if(cp is null) yield break; if(cp.Duration.Unit.Dimension!=AstronomyMeasurementDimension.Time) yield return Issue(AstronomyTemporalValidationCodes.CyclePeriodDimensionInvalid,"Cycle period duration must use time dimension.","$.pattern.cyclePeriod.duration",RuleId); foreach(var i in AstronomyTemporalMeasurementValidator.Validate(cp.Duration,"$.pattern.cyclePeriod.duration",RuleId,Domain,Family)) yield return i; if(p.Pattern.Recurrence.Kind==AstronomyRecurrenceKind.CalendarInterval) yield return Issue(AstronomyTemporalValidationCodes.CyclePeriodRecurrenceMismatch,"Cycle period is not compatible with calendar-interval recurrence.","$.pattern.cyclePeriod",RuleId);}}
